/* ---------- scale maps (schematic, monotone, vertically exaggerated) ------- */
function dToPix(d) { return 565 * Math.pow(Math.max(1, d) / 400, 0.2); }
function pixToD(p) { return 400 * Math.pow(Math.max(1, p) / 565, 5); }
function hToPix(h) { return 72.3 * Math.pow(Math.max(0.5, h), 0.35); }
function tToPix(t) { return 300 * Math.pow(Math.max(1, t) / 200, 0.3); }

/* ---------- helpers -------------------------------------------------------- */
function smooth(pts) {
  var d = 'M' + pts[0][0] + ',' + pts[0][1];
  for (var i = 0; i < pts.length - 1; i++) {
    var p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || pts[i + 1];
    d += ' C' + (p1[0] + (p2[0] - p0[0]) / 6).toFixed(1) + ',' + (p1[1] + (p2[1] - p0[1]) / 6).toFixed(1) +
         ' ' + (p2[0] - (p3[0] - p1[0]) / 6).toFixed(1) + ',' + (p2[1] - (p3[1] - p1[1]) / 6).toFixed(1) +
         ' ' + p2[0] + ',' + p2[1];
  }
  return d;
}
function norm(a) { while (a > Math.PI) a -= 2 * Math.PI; while (a < -Math.PI) a += 2 * Math.PI; return a; }
function arc(parent, cx, cy, r, a0, a1, w) {
  var delta = norm(a1 - a0), pts = [], n = 30;
  for (var i = 0; i <= n; i++) {
    var a = a0 + delta * i / n;
    pts.push((cx + r * Math.cos(a)).toFixed(1) + ',' + (cy + r * Math.sin(a)).toFixed(1));
  }
  parent.polyline(pts.join(' ')).fill('none').stroke({ color: '#000', width: w || 1.4 });
  return a0 + delta / 2;
}
function txt(parent, s, x, y, o) {
  o = o || {};
  var t = parent.plain(s).font({
    family: o.family || 'Georgia, "Times New Roman", serif',
    size: o.size || 27,
    anchor: o.anchor || 'middle'
  }).attr({ x: x, y: y }).fill(o.fill || '#000');
  if (o.halo !== false) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.haloW || 4, 'stroke-linejoin': 'round' });
  return t;
}
function hook(el, tip, title, body) {
  el.css('cursor', title ? 'pointer' : 'default');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
}
