var OCHRE_S = [[-10, 458], [40, 432], [90, 416], [150, 404], [210, 400], [258, 414], [300, 438],
               [350, 454], [410, 462], [462, 482], [512, 508], [552, 542], [590, 584]];
var OCHRE_T = [[-10, 246], [60, 252], [130, 270], [190, 302], [240, 348], [292, 398], [342, 444],
               [402, 492], [470, 528], [540, 556], [615, 584]];

/* ---------- physics -------------------------------------------------------- */
function singleSolve() {
  var alpha = Math.atan2(st.h, st.d);
  var eps = st.noise * Math.PI / 180;
  var lo = (alpha + eps < Math.PI / 2 - 1e-6) ? st.h / Math.tan(alpha + eps) : 1;
  var hi = (alpha - eps > 1e-5) ? st.h / Math.tan(alpha - eps) : 1e5;
  return { alpha: alpha, dlo: Math.max(5, lo), dhi: Math.min(9000, hi) };
}
function twoSolve(alpha) {
  var eps = st.noise * Math.PI / 180, t = st.t, d = st.d;
  var beta = Math.atan2(d * Math.sin(alpha), t - d * Math.cos(alpha));
  var lo = 1e9, hi = -1e9;
  for (var i = -1; i <= 1; i += 2) for (var j = -1; j <= 1; j += 2) {
    var a = alpha + i * eps, b = beta + j * eps, s = Math.sin(a + b);
    var dc = (Math.abs(s) < 1e-4) ? 9000 : t * Math.sin(b) / s;
    if (!isFinite(dc) || dc <= 0) dc = 9000;
    lo = Math.min(lo, dc); hi = Math.max(hi, dc);
  }
  return { alpha: alpha, beta: beta, dlo: Math.max(5, lo), dhi: Math.min(9000, hi) };
}

/* ---------- render --------------------------------------------------------- */
function render() {
