      .fill({ color: CWEDGE, opacity: 0.3 }).stroke('none');
    Lwedge.line(OBSX, eyeY, xa, FOOTY).stroke({ color: CWEDGE, width: 1.2, opacity: 0.55 });
    Lwedge.line(OBSX, eyeY, xb, FOOTY).stroke({ color: CWEDGE, width: 1.2, opacity: 0.55 });
