  var eye = Lboat.circle(38).center(OBSX, eyeY).fill('#fff').stroke({ color: '#000', width: 3.4 });
  hook(eye, 'Observer (eye / camera) at height h', 'The single observer',
    'One eye measures only a direction. It gets a distance because it also knows its own height above the water — that height is the hidden baseline.');

  /* angles */
