  var a2a = -Math.PI, a2b = Math.atan2(eyeY - FOOTY, OBSX - bx);
  var mid2 = arc(Lgeom, bx, FOOTY, 52, a2a, a2b);
  var lb = txt(Llab, 'α', bx + 76 * Math.cos(mid2), FOOTY + 76 * Math.sin(mid2) + 9);
