  var lh = txt(Llab, 'h', OBSX - 27, (eyeY + FOOTY) / 2 + 9);
  hook(lh, 'h = ' + st.h + ' m — the known baseline', 'Height is the baseline',
    'The only length known in advance is the observer\'s height above the water. Without it the angle α would be compatible with a boat at any range.');
  hook(Lgeom.line(OBSX, eyeY, OBSX, FOOTY).stroke({ color: '#000', width: 14, opacity: 0 }),
    'h = ' + st.h + ' m — the known baseline', 'Height is the baseline',
    'The only length known in advance is the observer\'s height above the water.');

