function renderTwo() {
  var tp = tToPix(st.t);
  var o2x = O1X + tp * Math.cos(BANG), o2y = O1Y + tp * Math.sin(BANG);
  var bx = O1X + dToPix(st.d), by = BOATY2;
  var aSight = Math.atan2(by - O1Y, bx - O1X);
  var alpha = BANG - aSight;
  var sol = twoSolve(alpha);

  Lland.path(smooth(OCHRE_T) + ' L -10,' + (FH + 4) + ' Z').fill(CLAND);

  var S = { color: '#000', width: 2.6, linecap: 'round' };

  /* wedge along the O1 sight line */
  if (st.noise > 0) {
    var ux = (bx - O1X), uy = (by - O1Y), ref = dToPix(st.d);
    function pAt(dd) {
      var k = Math.min(1.75, dToPix(dd) / ref);
      return [O1X + ux * k, O1Y + uy * k];
    }
    var pa = pAt(sol.dlo), pb = pAt(sol.dhi);
    var L = Math.sqrt(ux * ux + uy * uy), nx = -uy / L * 9, ny = ux / L * 9;
    var wp = Lwedge.polygon([[pa[0] + nx, pa[1] + ny], [pb[0] + nx, pb[1] + ny],
                             [pb[0] - nx, pb[1] - ny], [pa[0] - nx, pa[1] - ny]]
      .map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' '))
      .fill({ color: CWEDGE, opacity: 0.3 }).stroke('none');
    Lwedge.line(o2x, o2y, pa[0], pa[1]).stroke({ color: CWEDGE, width: 1.2, opacity: 0.55 });
    Lwedge.line(o2x, o2y, pb[0], pb[1]).stroke({ color: CWEDGE, width: 1.2, opacity: 0.55 });
    hook(wp, 'Uncertainty in d from ±' + st.noise.toFixed(1) + '° of angle error',
      'Why stereo wants a wide baseline',
      'The two rays cross at a shallow angle when t is small or d is large, so the crossing point slides far along the line of sight. Distance error grows like d²·δθ / t.');
  }

  Lgeom.line(O1X, O1Y, o2x, o2y).stroke(S);
  Lgeom.line(O1X, O1Y, bx, by).stroke(S);
  Lgeom.line(o2x, o2y, bx, by).stroke(S);

  /* right-angle marker on the baseline */
  var ux2 = Math.cos(BANG), uy2 = Math.sin(BANG);
  var proj = ((bx - O1X) * ux2 + (by - O1Y) * uy2);
  proj = Math.max(0.38 * tp, Math.min(0.78 * tp, proj));
  var fx = O1X + ux2 * proj, fy = O1Y + uy2 * proj, nnx = uy2, nny = -ux2, sq = 16;
  Lgeom.polygon([[fx, fy], [fx + ux2 * sq, fy + uy2 * sq],
